const body = $input.first().json.body || {};
const invoiceNumber = body.invoiceNumber || ('AST-' + new Date().getFullYear() + '-' + String(Date.now()).slice(-5));
const vatRate = body.vatRate ?? 0.21;
const lines = Array.isArray(body.lines) ? body.lines : [];
const subtotal = lines.reduce((sum, line) => sum + Number(line.qty || 1) * Number(line.unitPrice || 0), 0);
const vat = subtotal * vatRate;
const total = subtotal + vat;
const htmlRows = lines.map(line => '<tr><td>' + (line.description || 'Concepto') + '</td><td>' + (line.qty || 1) + '</td><td style="text-align:right">' + Number(line.unitPrice || 0).toFixed(2) + ' EUR</td><td style="text-align:right">' + (Number(line.qty || 1) * Number(line.unitPrice || 0)).toFixed(2) + ' EUR</td></tr>').join('');
const html = '<!doctype html><html><head><meta charset="utf-8"><title>Factura ' + invoiceNumber + '</title><style>body{font-family:Arial;margin:32px;color:#1f2933}header{border-bottom:3px solid #075b63;margin-bottom:20px}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #d8e0e7;padding:8px}th{text-align:left}.total{font-size:20px}</style></head><body><header><h1>Astoreka MTO</h1><p>Factura ' + invoiceNumber + '</p></header><p><strong>Cliente:</strong> ' + (body.clientName || 'Cliente pendiente') + '</p><p><strong>Direccion:</strong> ' + (body.clientAddress || '') + '</p><table><thead><tr><th>Concepto</th><th>Cantidad</th><th>Precio</th><th>Total</th></tr></thead><tbody>' + htmlRows + '</tbody></table><p>Subtotal: ' + subtotal.toFixed(2) + ' EUR</p><p>IVA: ' + vat.toFixed(2) + ' EUR</p><p class="total"><strong>Total: ' + total.toFixed(2) + ' EUR</strong></p></body></html>';
return [{ json: { type: 'factura', invoiceNumber, clientName: body.clientName, subtotal, vat, total, html, status: 'generated' } }];
